"""Bank table construction, exact-key entry counting and runtime matching.

A range bank needs one entry per kept cluster.  An exact bank has separate
tables per pattern length; each pattern denotes its Cartesian product of
integer interval values excluding 1514 at every coordinate.  Identical exact
keys of the same length occupy one entry (their action is the highest-priority
matching cluster); keys of different lengths are distinct.
"""
PAD = 1514
BASE = 3029


def range_entry_count(kept):
    return len(kept)


def _coord_sets(interval):
    """Allowed value set of [lo,hi] excluding 1514, as sorted (a,b) tuples."""
    lo, hi = interval
    if lo <= PAD <= hi:
        parts = []
        if lo <= PAD-1:
            parts.append((lo, PAD-1))
        if PAD+1 <= hi:
            parts.append((PAD+1, hi))
        return tuple(parts)
    return ((lo, hi),)


def _canonical(pattern):
    sets = tuple(_coord_sets(iv) for iv in pattern)
    for part in sets:
        if not part:
            return None
    return sets


def _volume(sets):
    v = 1
    for part in sets:
        total = 0
        for a, b in part:
            total += b - a + 1
        v *= total
    return v


def _powers(L):
    """pw[j] = BASE**(L-1-j) (big-endian mixed-radix encoding)."""
    p = [1]
    for _ in range(L-1):
        p.append(p[-1]*BASE)
    return p[::-1]


def _union_count(boxes, kcap):
    """min(number of distinct keys over the boxes, kcap).

    Every box volume is below kcap here (larger ones shortcut), so the total
    key enumeration is bounded by len(boxes)*(kcap-1)."""
    if kcap <= 0:
        return 0
    for box in boxes:
        if _volume(box) >= kcap:
            return kcap
    seen = set()
    for box in boxes:
        L = len(box)
        pw = _powers(L)
        if L == 1:
            for a, b in box[0]:
                seen.update(range(a, b+1))
                if len(seen) >= kcap:
                    return kcap
            continue
        # enumerate coordinate prefixes 0..L-2 recursively; the last
        # coordinate runs are contiguous integer ranges for fixed prefix
        stack = [(0, 0, 0)]        # (coordinate, part index, encoded prefix)
        while stack:
            j, idx, prefix = stack.pop()
            if j == L-1:
                for a, b in box[j]:
                    seen.update(range(prefix + a*pw[j], prefix + b*pw[j] + 1))
                if len(seen) >= kcap:
                    return kcap
                continue
            part = box[j][idx]
            if idx + 1 < len(box[j]):
                stack.append((j, idx+1, prefix))
            a, b = part
            if a == b:
                stack.append((j+1, 0, prefix + a*pw[j]))
            else:
                stack.append((j, 0, prefix + pw[j]))   # advance value a+1...
                stack[-1] = (j, 0, prefix + pw[j])
                stack.append((j+1, 0, prefix + a*pw[j]))
                # remaining values a+1..b handled by the advance entry, but
                # its own range is (a+1, b): emulate via a synthetic part
                stack[-2] = ('range', j, a+1, b, prefix + (a+1)*pw[j])
        if len(seen) >= kcap:
            return kcap
    return len(seen)


def exact_entry_count(patterns, cap_exact):
    """min(actual distinct keys, capacity.exact+1) across pattern lengths."""
    K = cap_exact + 1
    by_len = {}
    for pattern in patterns:
        by_len.setdefault(len(pattern), []).append(pattern)
    total = 0
    for L in sorted(by_len):
        seen = {}
        for pattern in by_len[L]:
            box = _canonical(pattern)
            if box is not None:
                seen[box] = None
        if seen:
            total += _union_count(list(seen), K - total)
            if total >= K:
                return K
    return total


class Matcher:
    """Highest-priority kept-cluster matching on sliding suffix windows."""

    def __init__(self, kept):
        """kept: [(cluster_id, class, range pattern)] in priority order."""
        by_len = {}
        for rank, (cid, cls, pattern) in enumerate(kept):
            by_len.setdefault(len(pattern), []).append((rank, cid, cls, pattern))
        self.groups = []
        for L, plist in by_len.items():
            plist.sort(key=lambda t: t[0])
            dicts = []
            for j in range(L):
                adds = {}
                rems = {}
                for i, (_, _, _, pattern) in enumerate(plist):
                    lo, hi = pattern[j]
                    adds.setdefault(lo, []).append(i)
                    rems.setdefault(hi+1, []).append(i)
                table = {}
                mask = 0
                for v in range(0, BASE):
                    for i in adds.get(v, ()):
                        mask |= 1 << i
                    for i in rems.get(v, ()):
                        mask ^= 1 << i
                    if mask:
                        table[v] = mask
                dicts.append(table)
            self.groups.append((L, plist, dicts))
        self.groups.sort(key=lambda g: g[1][0][0])

    def best(self, features, consumed):
        """(rank, cluster_id, class, length) of the highest-priority match of
        any suffix window ending at the last consumed packet, else None."""
        best = None
        for L, plist, dicts in self.groups:
            if L > consumed:
                continue
            if best is not None and plist[0][0] > best[0]:
