            print(' file', os.path.relpath(p, root), st.st_size, oct(st.st_mode), 'links', st.st_nlink)
        else:
            print(' dir ', os.path.relpath(p, root))
        assert stat.S_ISREG(st.st_mode) or stat.S_ISDIR(st.st_mode), p
print('entries:', count, 'bytes:', size)
assert count <= 4096 and size <= 64*1024**2
